def crypt_floor_id(floor):
    return f"crypt_floor_{int(floor)}"

def crypt_floor_number(room_id):
    m = re.fullmatch(r"crypt_floor_(\d+)(?:_r\d+)?", str(room_id))
    if not m: return None
    floor=int(m.group(1))
    return floor if floor >= 1 else None


